do $f6$
declare changed integer;
begin
  if exists (select 1 from public.tr_variant_types where boutique_id = '2b2b1a07-3a58-4422-bc67-e274b0fa6d1d'::uuid) then
    raise exception 'F6: the boutique already has variant types';
  end if;
  select count(*) into changed
  from f6_hash s left join public.tr_products p on p.id = s.id
  where p.id is null or p.merged_into is not null or md5(jsonb_build_array(p.title, p.description, p.description_html, p.status::text, p.product_type, p.stock, p.sizes, p.size_stocks, p.features, p.images, p.marketplace_images, p.lifestyle_images)::text) <> s.h;
  if changed > 0 then
    raise exception 'F6: % product(s) changed since the snapshot; re-run the script', changed;
  end if;
end
$f6$;
