insert into public.tr_product_variants (product_id, option_value_ids, stock, images, active, sort_order)
  select m.survivor, array[cv.id, sv.id],
    greatest(0, coalesce(round((mp.size_stocks ->> sv.label)::numeric), 0))::integer,
    m.gallery, true,
    (row_number() over (partition by m.survivor order by m.ord, sv.sort_order) - 1)::integer
  from f6_members m
  join public.tr_products mp on mp.id = m.member
  join f6_options o on o.product_id = m.survivor
  join public.tr_variant_type_values cv on cv.type_id = o.color_type and cv.label = m.value_label
  join public.tr_variant_type_values sv on sv.type_id = o.size_type and mp.sizes ? sv.label;
update public.tr_products p set
  title = s.title, description = d.description, description_html = d.description_html,
  images = coalesce((select jsonb_agg(x.u order by x.pos) from (select g.u, min(m.ord * 1000 + g.n) as pos from f6_members m, jsonb_array_elements_text(m.gallery) with ordinality g(u, n) where m.survivor = s.id group by g.u) x), '[]'::jsonb), marketplace_images = '[]'::jsonb, lifestyle_images = '[]'::jsonb,
  features = s.features, sizes = s.sizes
from (values ('a9db87a6-7a5a-4194-bde1-62af9a221926'::uuid, 'Pile Detaylı Kolsuz Bluz', 'a9db87a6-7a5a-4194-bde1-62af9a221926'::uuid, null::jsonb, '{"fit":"Regular","color":"Pembe","fabric":"Hafif dokuma","gender":"Kadın","neckHem":"Gömlek yaka, Fırfırlı kol, Dalgalı etek ucu","manualListing":true,"aiModelId":"studio:selin"}'::jsonb, '["XS","S","M","L","XL","2XL","3XL"]'::jsonb), ('1b79bc31-d0f8-4b5f-b136-83f1ebb7de65'::uuid, 'Fırfırlı Bluz', '1b79bc31-d0f8-4b5f-b136-83f1ebb7de65'::uuid, null::jsonb, '{"fit":"Regular","color":"Pembe","fabric":"Hafif dokuma","gender":"Kadın","neckHem":"Bisiklet yaka, Düğmeli ön","manualListing":true,"aiModelId":"studio:selin"}'::jsonb, '["XS","S","M","L","XL","2XL","3XL"]'::jsonb), ('8300c5b5-8802-4483-9368-01f9471f9f53'::uuid, 'Maxi Tek Omuz Elbise', '8300c5b5-8802-4483-9368-01f9471f9f53'::uuid, null::jsonb, '{"fit":"Regular","color":"Hardal","fabric":"Akışkan dokuma","gender":"Kadın","length":"Maxi","sleeves":"Kolsuz","neckline":"Tek omuz","aiModelId":"studio:selin","decollete":"Omuz","lifestyleModelIds":["studio:selin","studio:selin"],"manualListing":true}'::jsonb, '["XS","S","M","L","XL","2XL","3XL"]'::jsonb), ('8c7d5936-8186-42a0-bec3-d86c05afab7f'::uuid, 'Maxi Bisiklet Yaka Elbise', '8c7d5936-8186-42a0-bec3-d86c05afab7f'::uuid, null::jsonb, '{"fit":"bol","color":"Kahverengi","fabric":"Krep","gender":"Kadın","length":"Midi","zipper":"Sırt fermuar","sleeves":"Kolsuz","stretch":"Esnek değil","neckline":"Bisiklet yaka","aiModelId":"studio:selin","decollete":"Yok","silhouette":"A kesim","lifestyleModelIds":["studio:selin","studio:selin"],"manualListing":true}'::jsonb, '["XS","S","M","L","XL","2XL","3XL"]'::jsonb), ('30875216-4540-4da8-965b-cb098eb14347'::uuid, 'V Yaka Midi Elbise', '30875216-4540-4da8-965b-cb098eb14347'::uuid, null::jsonb, '{"length":"Midi","sleeves":"Üç çeyrek","neckline":"V yaka","aiModelId":"studio:selin","lifestyleModelIds":["studio:selin","studio:selin"],"color":"Krem","manualListing":true}'::jsonb, '["XS","S","M","L","XL","2XL","3XL"]'::jsonb), ('f952c9e0-c082-4084-ae16-adb4d53b7a4e'::uuid, 'Midi Straplez Elbise', 'f952c9e0-c082-4084-ae16-adb4d53b7a4e'::uuid, null::jsonb, '{"length":"Midi","sleeves":"Kolsuz","neckline":"Straplez","aiModelId":"studio:selin","decollete":"Yok","lifestyleModelIds":["studio:selin","studio:selin"],"color":"Beyaz","manualListing":true}'::jsonb, '["24","26","28","30","32","34","36","38","40","42","44","46","48","50","52"]'::jsonb), ('b1d3b265-66d4-4e25-ac00-4a50c4938dd0'::uuid, 'Ceket Pantolon Takım', 'b1d3b265-66d4-4e25-ac00-4a50c4938dd0'::uuid, null::jsonb, '{"color":"Pembe","setItems":[{"chips":{"fit":"Rahat","hem":null,"rise":null,"length":"Crop","sleeves":"Kısa kol","neckline":"Dik yaka","decollete":"Yok"},"family":"ust-giyim","category":"ceket"},{"chips":{"fit":"Wide","hem":"Bol","rise":"Yüksek bel","length":"Normal","sleeves":null,"neckline":null,"decollete":null},"family":"alt-giyim","category":"pantolon"}],"aiModelId":"studio:selin","uploadKind":"takim","lifestyleModelIds":["studio:selin","studio:selin"],"manualListing":true}'::jsonb, '["XS","S","M","L","XL","2XL","3XL"]'::jsonb), ('b69a3fd1-4a48-4a52-8ef1-8b39f92456c1'::uuid, 'Kemerli Pantolon', 'b69a3fd1-4a48-4a52-8ef1-8b39f92456c1'::uuid, null::jsonb, '{"fit":"Regular","rise":"Yüksek bel","length":"Normal","neckHem":"Düz","ornament":"Kemerli","aiModelId":"studio:selin","manualListing":true,"lifestyleModelIds":["studio:selin","studio:selin"],"color":"Kahverengi"}'::jsonb, '["24","26","28","30","32","34","36","38","40","42","44","46","48","50","52"]'::jsonb), ('0867af66-9b0a-421b-981d-d01ddfb5d4e6'::uuid, 'Midi Jean Elbise', '0867af66-9b0a-421b-981d-d01ddfb5d4e6'::uuid, null::jsonb, '{"color":"Espresso","gender":"Kadın","length":"Midi","zipper":"Yan fermuar","sleeves":"Kolsuz","stretch":"Hafif esnek","neckline":"V yaka","aiModelId":"studio:selin","decollete":"Hafif","silhouette":"Vücuda oturan","manualListing":true,"lifestyleModelIds":["studio:selin"]}'::jsonb, '["XS","S","M","L","XL","2XL","3XL"]'::jsonb)) as s(id, title, description_from, images, features, sizes)
join public.tr_products d on d.id = s.description_from
where p.id = s.id;
update public.tr_products p set status = 'hidden', merged_into = m.survivor,
  features = (p.features - 'colorGroupId' - 'colorSiblingIds') || jsonb_build_object('color', m.color)
from f6_members m where p.id = m.member and m.member <> m.survivor;
update public.tr_products set features = features - 'colorGroupId' - 'colorSiblingIds'
where id = any(array['5d6beba4-53d7-45d5-88ad-e132ba2d0f65'::uuid, '671a4ea7-e483-4f43-9522-573b8f7fbf52'::uuid, '21c7d4a2-96c3-4ec4-80a4-ac4e0e1c269c'::uuid, '4c5f40c6-3b40-4425-acc0-5215316cdcb1'::uuid, '683a3d5a-cdfc-43a7-8254-179ecadcc468'::uuid]::uuid[]);
update public.tr_products p set product_type = 'advanced', size_stocks = '{}'::jsonb,
  stock = coalesce((select sum(v.stock) from public.tr_product_variants v where v.product_id = p.id), 0)
from f6_options o where p.id = o.product_id;
update public.tr_products set updated_at = timezone('utc'::text, now()) where id in (select id from f6_hash);
commit;
